/* Intent: Analyze digital engagement patterns by customer cohorts over time 
   Knowledge: Digital First Customer (id:14) and Customer Engagement Score (CES, id:7)
   Advanced Features: Date binning, FILTER clause */
   WITH digital_cohorts AS (
    /* Step 1: Create quarterly cohorts based on customer tenure */
    SELECT 
        cr.clientref,
        DATE_TRUNC('quarter', (cr.scoredate - (cr.tenureyrs * INTERVAL '1 year'))) AS cohort_quarter,
        /* Properly implement KB#14 Digital First Customer definition */
        (bt.chaninvdatablock->>'onlineuse' = 'High' OR bt.chaninvdatablock->>'mobileuse' = 'High') 
        AND bt.chaninvdatablock->>'autopay' = 'Yes' AS is_digital_first,
        /* Calculate CES components */
        0.4 * cah.produsescore + 0.3 * cah.chanusescore + 0.2 * bt.bankrelscore + 0.1 * (cah.custservint::float/10) AS ces
    FROM core_record cr
    JOIN credit_accounts_and_history cah ON cr.coreregistry = cah.histcompref
    JOIN bank_and_transactions bt ON cah.histcompref = bt.bankexpref
    WHERE bt.chaninvdatablock IS NOT NULL
)
/* Step 2: Aggregate metrics by cohort and digital-first status */
SELECT 
    cohort_quarter,
    is_digital_first,
    COUNT(*) AS cohort_size,
    /* CES metrics */
    AVG(ces) AS avg_ces,
    /* Percentage with high engagement */
    COUNT(*) FILTER (WHERE ces > 0.7)::float / COUNT(*) AS pct_high_engagement,
    /* Digital-first high engagement rate */
    COUNT(*) FILTER (WHERE is_digital_first AND ces > 0.7)::float / 
        NULLIF(COUNT(*) FILTER (WHERE is_digital_first), 0) AS digital_first_high_engagement_rate
FROM digital_cohorts
GROUP BY cohort_quarter, is_digital_first
ORDER BY cohort_quarter, is_digital_first DESC;

-------------------------------------------------------------------------
-- Create a Function to Calculate Credit Health Score (CHS)
-- -----------------------------------------------------------------------
-- This function computes the composite Credit Health Score (CHS)
-- according to KB "Credit Health Score (CHS)" (KB id:5):
-- Step 1: Define the input parameters.
-- Step 2: Calculate each component using arithmetic and typecasting.
-- Step 3: Sum up the components for the final CHS value.
CREATE OR REPLACE FUNCTION calculate_credit_health_score(
    p_credscore    SMALLINT,
    p_credutil     NUMERIC(5,3),
    p_debincratio  NUMERIC(5,3),
    p_credageyrs   SMALLINT,
    p_delinqcount  SMALLINT,
    p_latepaycount SMALLINT,
    p_choffs       SMALLINT,
    p_bankr        SMALLINT
)
RETURNS NUMERIC(5,3)
LANGUAGE plpgsql
AS $$
DECLARE
    comp1 NUMERIC(5,3);
    comp2 NUMERIC(5,3);
    comp3 NUMERIC(5,3);
    comp4 NUMERIC(5,3);
    comp5 NUMERIC(5,3);
    total NUMERIC(5,3);
BEGIN
    -- Step 1: Compute 0.4 * (credscore/850)
    comp1 := 0.4 * (p_credscore::NUMERIC / 850);
    -- Step 2: Compute 0.2 * (1 - credutil)
    comp2 := 0.2 * (1 - p_credutil);
    -- Step 3: Compute 0.2 * (1 - debincratio)
    comp3 := 0.2 * (1 - p_debincratio);
    -- Step 4: Compute 0.1 * (credageyrs/20)
    comp4 := 0.1 * (p_credageyrs::NUMERIC / 20);
    -- Step 5: Compute 0.1 * (1 - ((delinqcount + latepaycount + choffs + bankr)/10))
    comp5 := 0.1 * (1 - ((p_delinqcount + p_latepaycount + p_choffs + p_bankr)::NUMERIC / 10));
    -- Final CHS computed as the sum of the individual components.
    total := comp1 + comp2 + comp3 + comp4 + comp5;
    RETURN total;
END;
$$;

ALTER TABLE transactions ADD COLUMN adjusted_esccomprate NUMERIC;

UPDATE transactions
SET adjusted_esccomprate = (
    SELECT esccomprate
    FROM markets
    WHERE markets.mktregistry = transactions.mktref
);       

CREATE INDEX idx_transaction_anomaly ON transactions (
    (payamtusd/1000 * txfinishhrs/24 * (1 + escrowhrs::numeric/100) * (1 - adjusted_esccomprate/100))
);

